using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {
 internal static class BuddyInteractivePolicyTests {
  static int checks;static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  static void Check(bool good,string name){if(!good)throw new Exception("FAIL "+name);checks++;Console.WriteLine("PASS "+name);}
  static void Put(string path,string body){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,body,new UTF8Encoding(false));}
  sealed class Fixture {internal readonly string Root,Game,User,Data,BuddyJar;internal readonly Engine Engine;internal readonly LauncherComponents Components;internal Fixture(string root){Root=root;Game=Path.Combine(root,"game");User=Path.Combine(root,"user");Data=Path.Combine(root,"data");foreach(string file in new[]{"ProjectZomboid64.exe","projectzomboid.jar","jre64/bin/java.exe","jre64/bin/server/jvm.dll","steam_api64.dll","ZNetJNI64.dll","Lighting64.dll"})Put(Path.Combine(Game,file),"isolated placeholder; never execute");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"mainClass\":\"zombie/gameStates/MainScreenState\",\"classpath\":[\"projectzomboid.jar\"],\"vmArgs\":[\"-Xmx2g\"]}");Put(Path.Combine(User,"mods/default.txt"),"VERSION = 1,\nmods\n{\n mod = Plain,\n}\nmaps\n{\n}\n");Put(Path.Combine(User,"mods/Plain/42/mod.info"),"id=Plain\n");string buddy=Path.Combine(User,"mods/ZombieBuddy");Put(Path.Combine(buddy,"42/mod.info"),"id=ZombieBuddy\n");BuddyJar=Path.Combine(buddy,"libs/ZombieBuddy.jar");Directory.CreateDirectory(Path.GetDirectoryName(BuddyJar));File.Copy(Path.Combine(Environment.CurrentDirectory,"Dependencies/ZombieBuddy-v2.3.4.jar"),BuddyJar);Engine=new Engine(Game,User,Data,true,null,_=>new System.Diagnostics.Process[0]);Engine.BindConfiguration(new LaunchConfigurationProfiles(Data,Game,User).Resolve("launcher"));Components=Engine.OwnedComponents();Components.Select(buddy,"ZombieBuddy",true,CancellationToken.None);Components.SaveOrdinary(new[]{"Plain"},CancellationToken.None);}}
  static void Policy(LiveModDiscovery.Session session,string label){string[] buddy=session.VmArguments.Where(arg=>arg.StartsWith("-javaagent:")&&arg.Contains("ZombieBuddy.jar=")).ToArray();Check(buddy.Length==1&&buddy[0].EndsWith("=prop_prefix=zb,policy=prompt",StringComparison.Ordinal),label+" keeps Buddy native prompt enabled for later unknown server JARs");Check(!session.VmArguments.Any(arg=>arg.Contains("deny-new")||arg.Contains("allow-all")||arg.Contains("frontend=")),label+" neither blocks in advance nor auto-authorizes or replaces native frontend");string config=session.VmArguments.Single(arg=>arg.StartsWith("-Dzb.config_dir=")).Substring(16);var settings=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(config,"config.json")));Check(((Dictionary<string,object>)settings["preload_mods"]).Count==0&&((IEnumerable)settings["trusted_authors"]).Cast<object>().Count()==0,label+" does not add automatic preload or trusted-author grants");var approvals=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(config,"mod_approvals.json")));Check(((IEnumerable)approvals["mods"]).Cast<object>().Count()==0,label+" does not invent server Java approval decisions");}
  static void Stage(string root,string kind,string mode,string label){var f=new Fixture(root);byte[] original=File.ReadAllBytes(f.Engine.Mods),config=File.ReadAllBytes(f.Engine.Config);string sourceHash=LauncherComponents.HashFile(f.BuddyJar);var request=kind=="server"?new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=1,Username="isolated",ServerComponents=mode}:kind=="save"?new ProfileLaunchRequest{Kind="save",Mode="Sandbox",Save="Fixture"}:new ProfileLaunchRequest{Kind="normal"};LaunchProfiles.Stage(f.Engine,request);try{Policy(f.Engine.LiveSession,label);string arguments=LaunchProfiles.BuildStartInfo(f.Engine).Arguments;Check(arguments.Contains("policy=prompt")&&!arguments.Contains("deny-new")&&!arguments.Contains("allow-all"),label+" actual production process arguments preserve prompt");Check(original.SequenceEqual(File.ReadAllBytes(f.Engine.Mods))&&config.SequenceEqual(File.ReadAllBytes(f.Engine.Config)),label+" staging preserves player mod list and launch JSON bytes");}finally{LaunchProfiles.Recover(f.Engine,true);}Check(!LaunchProfiles.Pending(f.Engine)&&original.SequenceEqual(File.ReadAllBytes(f.Engine.Mods))&&config.SequenceEqual(File.ReadAllBytes(f.Engine.Config))&&LauncherComponents.HashFile(f.BuddyJar)==sourceHash,label+" recovery clears only owned session and preserves source");}
  [STAThread]static int Main(string[] args){try{Console.OutputEncoding=new UTF8Encoding(false);string root=args[0];Directory.CreateDirectory(root);Stage(Path.Combine(root,"menu"),"normal",null,"main menu then manual connection");Stage(Path.Combine(root,"save"),"save",null,"continue save then manual connection");Stage(Path.Combine(root,"direct"),"server","follow-server","direct server");Stage(Path.Combine(root,"force"),"server","force-local","direct server with local components");Stage(Path.Combine(root,"reconnect"),"server","follow-server","new connection session");var f=new Fixture(Path.Combine(root,"vanilla"));var vanilla=new LauncherComponents(f.Engine.OwnedConfiguration.Bind("vanilla"),new Version(42,0));var prepared=LiveModDiscovery.Prepare(vanilla,BundledAssets.ReadOwnAsset("OrangeLive.jar"),new SaveProfiles.Entry[0],CancellationToken.None,null);Check(!prepared.VmArguments.Any(arg=>arg.Contains("ZombieBuddy")||arg.Contains("policy=")),"vanilla without Buddy does not gain a Java loader or approvals");Console.WriteLine("PASS Buddy interactive policy: "+checks+" checks");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
 }
}